import{_ as e,o as s,c as o,a2 as a}from"./chunks/framework.NwY0f7AV.js";const u=JSON.parse('{"title":"Devtools","description":"","frontmatter":{},"headers":[],"relativePath":"guide/devtools.md","filePath":"guide/devtools.md"}'),n={name:"guide/devtools.md"};function i(r,t,h,l,d,c){return s(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="devtools" tabindex="-1">Devtools <a class="header-anchor" href="#devtools" aria-label="Permalink to &quot;Devtools&quot;">​</a></h1><p>wraith&#39;s repository includes a local web UI for running wraith one action at a time and seeing exactly what each did. It&#39;s for developing scrapers and working on wraith itself. It isn&#39;t part of the npm package, so run it from a clone of the repository:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/praneth2580/WRAITH.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> WRAITH</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chromium</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> devtools</span></span></code></pre></div><p>Then open <strong><a href="http://127.0.0.1:4477" target="_blank" rel="noreferrer">http://127.0.0.1:4477</a></strong>. Set <code>PORT</code> to use another port: <code>PORT=4478 npm run devtools</code>.</p><h2 id="the-layout" tabindex="-1">The layout <a class="header-anchor" href="#the-layout" aria-label="Permalink to &quot;The layout&quot;">​</a></h2><p><strong>Left: Browser and Action.</strong> The Browser panel sets the engine, human preset, after-action wait, consent choice and blocked resources; any other option goes in as JSON (for example <code>{ &quot;ai&quot;: { &quot;provider&quot;: &quot;ollama&quot;, &quot;model&quot;: &quot;qwen2.5:7b&quot; } }</code>). Untick <strong>Headless</strong> to watch the real window. The Action panel runs one of 38 actions: every page method, plus <code>fetch</code> without a browser and <code>evaluate</code> for your own JavaScript.</p><p>Targets are typed as a selector or as JSON: <code>{&quot;role&quot;: &quot;button&quot;, &quot;name&quot;: &quot;Sign in&quot;}</code>, <code>{&quot;label&quot;: &quot;Email&quot;}</code>, <code>{&quot;text&quot;: &quot;/next/i&quot;}</code> (slashes make a RegExp).</p><p><strong>Middle: the page.</strong> A URL bar, and the screenshot of the selected action. <strong>After</strong> shows the page once the action finished; <strong>At click</strong> shows it just before the mouse button went down, with the mouse path drawn on top:</p><ul><li>the blue ring is where the cursor started, and the line runs from blue to red over time;</li><li>each dot is one mouse event, so wide gaps mean fast movement;</li><li>the red ring is where it pressed.</li></ul><p><strong>Right: the timeline.</strong> Every action you&#39;ve run, with its duration; red ones failed. Click one to see it again.</p><h2 id="the-tabs" tabindex="-1">The tabs <a class="header-anchor" href="#the-tabs" aria-label="Permalink to &quot;The tabs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tab</th><th>Shows</th></tr></thead><tbody><tr><td>Result</td><td>What the action returned, images (such as a CAPTCHA), or the error and stack. <strong>Run again</strong> and <strong>Load into the form</strong></td></tr><tr><td>Mouse &amp; keys</td><td>Path length against a straight line, top speed, pause before pressing, press duration; every keystroke with the gap since the previous one, typos highlighted</td></tr><tr><td>Network</td><td>Every request the action made, with status, type and timing. Click one to see its response body</td></tr><tr><td>Console</td><td>What the page logged, including JavaScript errors</td></tr><tr><td>Log</td><td>wraith&#39;s own log for the action</td></tr><tr><td>Code</td><td>The action as wraith code, and every successful step so far as one script</td></tr></tbody></table><h2 id="diagnosing" tabindex="-1">Diagnosing <a class="header-anchor" href="#diagnosing" aria-label="Permalink to &quot;Diagnosing&quot;">​</a></h2><ul><li><strong>A click doesn&#39;t work:</strong> run <strong>inspect</strong> with the same target. It outlines every match on the screenshot, marks the one wraith uses, and says whether it&#39;s hidden, disabled, off screen or covered (and by what).</li><li><strong>Possible bot traps:</strong> run <strong>honeypots</strong>. It outlines, in red, the links, buttons and fields a person couldn&#39;t see, with the reason for each.</li><li><strong>A page never settles:</strong> run <strong>activity</strong> or <strong>waitForSettled</strong>. They list requests in flight, visible loaders, and when the content last changed.</li><li><strong>Classes are generated:</strong> run an action that loads data, open <strong>Network</strong>, and look for JSON responses. Then try <strong>captureJson</strong> with that URL, and <strong>structuredData</strong>.</li></ul><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><ul><li>One action runs at a time.</li><li>With <code>human: &#39;off&#39;</code> there&#39;s no mouse path, because clicks don&#39;t move the mouse.</li><li>Taking the &quot;At click&quot; screenshot delays the first press of each action by about 0.1 s.</li><li>If you close a visible browser window, the next action opens a new browser with the same settings.</li><li>The server only listens on 127.0.0.1, and its API needs a token that only its own page has, so websites open in the driven browser can&#39;t control it.</li></ul>`,16)])])}const g=e(n,[["render",i]]);export{u as __pageData,g as default};
